(()=>{try{const c=window.siteMasterAnalytics;if(!c||!c.endpoint)return;const q=new URLSearchParams(location.search),p={post_id:c.postId,token:c.token,referrer:document.referrer?new URL(document.referrer).hostname:""};["utm_source","utm_medium","utm_campaign","utm_term","utm_content"].forEach(k=>{const v=q.get(k);v&&(p[k]=v.slice(0,150))});const b=new Blob([JSON.stringify(p)],{type:"application/json"});if(navigator.sendBeacon&&navigator.sendBeacon(c.endpoint,b))return;fetch(c.endpoint,{method:"POST",body:JSON.stringify(p),headers:{"Content-Type":"application/json"},credentials:"same-origin",keepalive:true}).catch(()=>{})}catch(e){}})();
